<?php
namespace Database\Seeders;use App\Models\{HmsPermission,SystemSetting};use Illuminate\Database\Seeder;use Illuminate\Support\Facades\DB;
class HotelManagementSeeder extends Seeder{public function run():void{$items=['management.view'=>'View management analytics','management.budgets'=>'Manage budgets','reports.consolidated'=>'View consolidated reports','security.audit'=>'View security and audit events','backups.manage'=>'Manage backups','settings.manage'=>'Manage system settings','permissions.manage'=>'Manage permissions'];foreach($items as $name=>$label){[$module]=explode('.',$name);HmsPermission::updateOrCreate(['name'=>$name],['label'=>$label,'module'=>$module]);}foreach(['super_admin','hotel_owner','general_manager'] as $role){foreach(HmsPermission::pluck('id') as $id)DB::table('hms_role_permissions')->updateOrInsert(['role'=>$role,'permission_id'=>$id],['created_at'=>now(),'updated_at'=>now()]);}}}
